mapper.insert:
INSERT INTO message (
    user_id, content, create_time, update_time, status, content_status
) VALUES (
    #{userId}, #{content}, NOW(), NOW(), #{status}, 'PENDING'
)

mapper.select:
SELECT COUNT(1)
FROM message
WHERE user_id = #{userId}
  AND create_time >= #{since}
  AND LOWER(TRIM(content)) = LOWER(TRIM(#{content}))
